/** Optional shared progress. Failure never blocks local reading or starts Gecko. */
public final class ServerBridge {
    static final ScheduledThreadPoolExecutor worker=new ScheduledThreadPoolExecutor(1);
    static final ThreadLocal<Boolean> applying=new ThreadLocal<>();
    static final Object fastGate=new Object();static final ExecutorService positionWorker=Executors.newSingleThreadExecutor();
    static final Object gate=new Object();static ScheduledFuture<?> scheduled;
    static volatile String activeBook="";
    static final java.util.concurrent.atomic.AtomicBoolean queued=new java.util.concurrent.atomic.AtomicBoolean();
    static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences("server_bridge",0);}
    static boolean enabled(Context c){return !prefs(c).getString("token","").isEmpty();}
    static boolean importing(){return Boolean.TRUE.equals(applying.get());}
    static void status(Context c,String text){prefs(c).edit().putString("status",text).apply();}
    static String visibleStatus(Context c){return prefs(c).getString("position_status",enabled(c)?"Tiến độ tự gửi khi rời chương":"Chưa liên kết server");}
    static void positionStatus(Context c,String event,String text){if(!event.isEmpty()&&!event.equals(prefs(c).getString("latest_local_event","")))return;if(text.equals(visibleStatus(c)))return;prefs(c).edit().putString("position_status",text).apply();c.sendBroadcast(new Intent(Repository.EVENT).setPackage(c.getPackageName()).putExtra("position_sync",true));}
    static void acknowledge(Context c,JSONObject pending){String title=Store.get(c).book(pending.optString("book"))==null?"":Store.get(c).book(pending.optString("book")).title;String time=new java.text.SimpleDateFormat("HH:mm:ss",java.util.Locale.ROOT).format(new java.util.Date());positionStatus(c,pending.optString("event_id"),"✓ Đã gửi vị trí · "+time+"\n"+title);}
    static boolean hasUnsent(Context c,String bid){String saved=prefs(c).getString("pending:"+bid,"");try{return !saved.isEmpty()&&!new JSONObject(saved).optString("event_id").equals(prefs(c).getString("home_fast:"+bid,""));}catch(Exception bad){return !saved.isEmpty();}}
    static void rememberLatest(Context c,String bid){if(bid.isEmpty()||!activeBook.isEmpty())return;String local=c.getSharedPreferences("settings",0).getString("lastBook","");if(hasUnsent(c,local))return;c.getSharedPreferences("settings",0).edit().putString("lastBook",bid).apply();c.sendBroadcast(new Intent(Repository.EVENT).setPackage(c.getPackageName()).putExtra("books_changed",true));}
    static String resumeLatest(Context c,String fallback)throws Exception{if(!enabled(c)||!ReadSync.connected(c))return fallback;String observed=prefs(c).getString("latest_local_event","");fastPositions(c,new RelayClient(c));try{JSONObject reply=request(c,"GET","/v3/pocket/resume",null,true,1500,3500);JSONObject document=reply.optJSONObject("document");if(document==null||!observed.equals(prefs(c).getString("latest_local_event","")))return fallback;String bid=document.getJSONObject("book").getString("id");if(hasUnsent(c,fallback))return fallback;apply(c,document,true);rememberLatest(c,bid);return bid;}catch(Exception unavailable){positionStatus(c,"","Chưa nhận được vị trí chung · Dùng bản đã lưu");return fallback;}}
    public static void localPosition(Context context,String book,String chapter,int paragraph,float fraction){
        if(importing()||!enabled(context)||book.equals("demo"))return;
        Context c=context.getApplicationContext();ContentUpload.enqueue(c,book,chapter);Store.Book local=Store.get(c).book(book);synchronized(gate){try{android.content.SharedPreferences p=prefs(c);long seq=p.getLong("sequence",0)+1;JSONObject pending=new JSONObject().put("last_read_at",local==null?System.currentTimeMillis():local.stamp).put("visits",local==null?0:local.visits).put("position_policy","latest").put("book",book).put("chapter",chapter).put("paragraph",paragraph).put("fraction",fraction).put("sequence",seq).put("event_id",UUID.randomUUID().toString()).put("relay_base_revision",new RelayClient(c).revision(book)).put("base_revision",p.getLong("revision:"+book,0)).put("session",p.getString("session:"+book,""));if(pending.optString("session").isEmpty()){pending.put("session",UUID.randomUUID().toString());}p.edit().putString("latest_local_event",pending.getString("event_id")).putLong("sequence",seq).putString("session:"+book,pending.getString("session")).putString("pending:"+book,pending.toString()).remove("cloud_pending:"+book).remove("resume_locator:"+book).commit();positionStatus(c,pending.getString("event_id"),"Chờ gửi vị trí · "+(local==null?book:local.title));}catch(Exception ignored){}BridgeJob.schedule(c);if(scheduled==null||scheduled.isDone())scheduled=worker.schedule(()->sync(c),DeviceProfile.eink(c)?60000:3000,TimeUnit.MILLISECONDS);}
    }
    public static void completed(Context c,String book){if(importing()||!enabled(c))return;Store.Book b=Store.get(c).book(book);if(b!=null&&!b.current.isEmpty())localPosition(c,book,b.current,b.pos,b.fraction);}
    public static void flags(Context c,String book){if(importing()||!enabled(c))return;synchronized(gate){android.content.SharedPreferences p=prefs(c);p.edit().putBoolean("flags:"+book,true).putLong("flag_revision:"+book,p.getLong("flag_revision:"+book,0)+1).commit();}BridgeJob.schedule(c);kick(c);}
    static void flushFlags(Context c)throws Exception{
        android.content.SharedPreferences p=prefs(c);Store store=Store.get(c);
        for(String key:p.getAll().keySet())if(key.startsWith("flags:")&&p.getBoolean(key,false)){
            String bid=key.substring(6);long revision=p.getLong("flag_revision:"+bid,0);
            Store.Book b=store.book(bid);boolean completed=store.isCompleted(bid);
            if(revision!=p.getLong("flag_revision:"+bid,0))continue;
            if(b==null)continue;publishMetadata(c,b);request(c,"POST","/v1/books/"+bid+"/flags",new JSONObject().put("favorite",b.pinned).put("completed",completed),true);
            synchronized(gate){if(revision==p.getLong("flag_revision:"+bid,0))p.edit().remove(key).commit();}
        }
    }
    public static void kick(Context context){if(!enabled(context))return;Context c=context.getApplicationContext();synchronized(gate){if(scheduled!=null){scheduled.cancel(false);scheduled=null;}}positionWorker.execute(()->{fastPositions(c,new RelayClient(c));if(queued.compareAndSet(false,true))worker.execute(()->{queued.set(false);sync(c);});});}
    static JSONObject request(Context c,String method,String path,JSONObject value,boolean auth)throws Exception{return request(c,method,path,value,auth,5000,10000);}
    static JSONObject request(Context c,String method,String path,JSONObject value,boolean auth,int connectTimeout,int readTimeout)throws Exception{
        URL url=new URL(prefs(c).getString("server","https://nanains.duckdns.org/hako")+path);if(!url.getProtocol().equals("https")||url.getUserInfo()!=null)throw new IOException("Cần địa chỉ HTTPS");HttpsURLConnection connection=(HttpsURLConnection)url.openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(connectTimeout);connection.setReadTimeout(readTimeout);connection.setRequestMethod(method);if(auth)connection.setRequestProperty("Authorization","Bearer "+prefs(c).getString("token",""));
        try{if(value!=null){connection.setDoOutput(true);connection.setRequestProperty("Content-Type","application/json");try(OutputStream out=connection.getOutputStream()){out.write(value.toString().getBytes(StandardCharsets.UTF_8));}}int code=connection.getResponseCode();if(code<200||code>=300)throw new IOException("Đồng bộ đang chờ ("+code+")");try(InputStream in=connection.getInputStream()){ByteArrayOutputStream data=new ByteArrayOutputStream();byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(data.size()+n>8*1024*1024)throw new IOException("Dữ liệu quá lớn");data.write(buffer,0,n);}return new JSONObject(data.toString("UTF-8"));}}finally{connection.disconnect();}
    }
    static ArrayList<String> paragraphs(Context c,Store store,String cid){
        ArrayList<String> rows=new ArrayList<>();try{
            File file=store.html(cid);if(file.length()>4*1024*1024)return rows;
            Element body=Jsoup.parseBodyFragment(Store.read(file)).body();if(!DeviceProfile.images(c))body.select("img").remove();
            for(Element e:new ArrayList<Element>(body.select("details"))){Element summary=e.selectFirst("summary");if(summary!=null)summary.remove();e.replaceWith(new Element("span").text(" [✎] "));}
            for(Element e:body.children()){
                String raw=Html.fromHtml(e.outerHtml(),Html.FROM_HTML_MODE_LEGACY).toString();int start=0,end=raw.length();
                while(end>0&&(raw.charAt(end-1)=='\n'||raw.charAt(end-1)=='\r'||raw.charAt(end-1)==' '))end--;
                while(start<end&&(raw.charAt(start)=='\n'||raw.charAt(start)=='\r'))start++;
                if(end>start)rows.add(raw.substring(start,end));
            }
        }catch(Exception ignored){}return rows;
    }
    static JSONObject locator(Context c,Store store,JSONObject pending)throws Exception{
        ContentAnchor.Capture anchor=ContentAnchor.capture(paragraphs(c,store,pending.getString("chapter")),pending.optInt("paragraph"),(float)pending.optDouble("fraction"));
        JSONObject value=new JSONObject().put("paragraph",pending.optInt("paragraph")).put("fraction",anchor.fraction).put("quote",anchor.quote)
            .put("last_read_at",pending.optLong("last_read_at")).put("visits",pending.optInt("visits"));
        if(anchor.textParagraph>=0)value.put("text_paragraph",anchor.textParagraph);return value;
    }
    static ContentAnchor.Position mapped(Context c,Store store,String cid,JSONObject loc){
        return ContentAnchor.resolve(paragraphs(c,store,cid),loc.optInt("paragraph"),loc.has("text_paragraph")&&!loc.isNull("text_paragraph")?loc.optInt("text_paragraph"):-1,(float)loc.optDouble("fraction"),loc.optString("quote"));
    }
    static void remapResume(Context c,String bid,String cid)throws Exception{
        android.content.SharedPreferences p=prefs(c);String saved=p.getString("resume_locator:"+bid,"");
        if(saved.isEmpty()||!activeBook.isEmpty()||p.contains("pending:"+bid))return;
        JSONObject waiting=new JSONObject(saved);if(!cid.equals(waiting.optString("chapter")))return;
        Store store=Store.get(c);if(!store.html(cid).isFile())return;
        ContentAnchor.Position mapped=mapped(c,store,cid,waiting.getJSONObject("locator"));
        synchronized(store){synchronized(gate){if(!saved.equals(p.getString("resume_locator:"+bid,""))||p.contains("pending:"+bid))return;
            Store.Book book=store.book(bid);if(book==null||!cid.equals(book.current))return;
            applying.set(true);try{store.position(bid,cid,mapped.paragraph,mapped.fraction);}finally{applying.remove();}
            p.edit().remove("resume_locator:"+bid).commit();
        }}
    }
    static void resumePosition(Context c,String bid){if(!enabled(c)||!ReadSync.connected(c)||!activeBook.isEmpty())return;android.content.SharedPreferences p=prefs(c);String captured=p.getString("pending:"+bid,""),observed=p.getString("latest_local_event","");try{if(!captured.isEmpty()){String event=new JSONObject(captured).optString("event_id");if(!event.equals(p.getString("home_fast:"+bid,""))&&!event.equals(p.getString("cloud_fast:"+bid,"")))return;}JSONObject position=null;try{position=request(c,"GET","/v3/pocket/position/"+bid,null,true,1000,1500).optJSONObject("position");}catch(Exception homeUnavailable){RelayClient cloud=new RelayClient(c);if(cloud.ready()){JSONArray positions=cloud.fastSnapshot(bid).optJSONArray("positions");for(int n=0;positions!=null&&n<positions.length();n++)if(bid.equals(positions.getJSONObject(n).optString("book")))position=positions.getJSONObject(n);}}if(position==null||!activeBook.isEmpty()||!captured.equals(p.getString("pending:"+bid,""))||!observed.equals(p.getString("latest_local_event","")))return;Store.Book book=Store.get(c).book(bid);if(book==null)return;JSONObject data=new JSONObject().put("book",new JSONObject().put("id",bid).put("title",book.title).put("url",book.url)).put("chapters",new JSONArray()).put("read",new JSONArray()).put("position",position);apply(c,data,true);}catch(Exception unavailable){/* Local checkpoint is immediately usable offline. */}}
    static void fastPositions(Context c,RelayClient cloud){if(!enabled(c)||!ReadSync.connected(c))return;synchronized(fastGate){android.content.SharedPreferences p=prefs(c);Store store=Store.get(c);for(Map.Entry<String,?> entry:p.getAll().entrySet()){if(!entry.getKey().startsWith("pending:"))continue;try{JSONObject pending=new JSONObject(String.valueOf(entry.getValue()));String bid=pending.getString("book"),event=pending.getString("event_id");Store.Chapter chapter=store.chapter(bid,pending.getString("chapter"));if(chapter==null)continue;JSONObject location=locator(c,store,pending);long sequence=pending.getLong("sequence")*2;
        if(!event.equals(p.getString("home_fast:"+bid,"")))try{positionStatus(c,event,"Đang gửi vị trí lên server…");Store.Book owner=store.book(bid);JSONObject payload=new JSONObject().put("book",new JSONObject().put("title",owner.title).put("url",owner.url)).put("chapter_title",chapter.title).put("chapter_url",chapter.url).put("locator",location).put("sequence",sequence).put("event_id","fast-"+event).put("session",pending.getString("session"));JSONObject result=request(c,"POST","/v3/pocket/position",payload,true,1500,2500);if(result.optBoolean("accepted")){android.content.SharedPreferences.Editor edit=p.edit().putString("home_fast:"+bid,event);if(result.has("revision"))edit.putLong("revision:"+bid,result.optLong("revision"));edit.apply();acknowledge(c,pending);}else positionStatus(c,event,"Chờ gửi vị trí · Server chưa nhận");}catch(Exception unavailable){positionStatus(c,event,"Chờ kết nối · Vị trí vẫn lưu trên máy");}
        if(cloud.ready()&&!event.equals(p.getString("cloud_fast:"+bid,"")))try{JSONObject payload=new JSONObject().put("book",bid).put("chapter",RelayClient.chapterId(chapter.url)).put("locator",location).put("read_ids",new JSONArray()).put("sequence",sequence).put("event_id","fast-"+event).put("session",pending.getString("session")).put("relay_base_revision",pending.optLong("relay_base_revision"));JSONObject result=cloud.send(payload);if(result.optBoolean("accepted"))p.edit().putString("cloud_fast:"+bid,event).apply();}catch(Exception unavailable){}
    }catch(Exception invalid){}}}}
    static JSONObject metadata(Context c,Store.Book b)throws Exception{Store store=Store.get(c);JSONArray links=new JSONArray(),read=new JSONArray();List<Store.Chapter> chapters=store.chapters(b.id);for(Store.Chapter ch:chapters)links.put(new JSONObject().put("title",ch.title).put("url",ch.url));for(String id:store.readingIds(b.id,chapters))read.put(id);JSONObject payload=new JSONObject().put("book",new JSONObject().put("title",b.title).put("url",b.url)).put("chapters",links).put("read",read);return payload;}
    static void publishMetadata(Context c,Store.Book b)throws Exception{request(c,"POST","/v3/pocket/metadata",metadata(c,b),true);}
    static boolean seedIndex(Context c)throws Exception{Store store=Store.get(c);android.content.SharedPreferences p=prefs(c),settings=c.getSharedPreferences("settings",0);JSONArray entries=new JSONArray();boolean more=false;for(Store.Book b:store.books()){if(p.getBoolean("index_seeded:"+b.id,false)||b.id.equals("demo")||settings.getBoolean("remote_metadata_only_"+b.id,false))continue;List<Store.Chapter> chapters=store.chapters(b.id);boolean stored=false;for(Store.Chapter ch:chapters)if(ch.ready){stored=true;break;}if(b.stamp==0&&!b.pinned&&!store.isCompleted(b.id)&&!stored)continue;if(entries.length()>=8){more=true;break;}JSONArray links=new JSONArray(),read=new JSONArray();for(Store.Chapter ch:chapters)if(!store.isHidden(b.id,ch.id))links.put(new JSONObject().put("title",ch.title).put("url",ch.url));for(String id:store.readingIds(b.id,chapters))read.put(id);JSONObject entry=new JSONObject().put("book",new JSONObject().put("title",b.title).put("url",b.url)).put("chapters",links).put("read",read).put("favorite",b.pinned).put("completed",store.isCompleted(b.id));Store.Chapter current=store.chapter(b.id,b.current);if(b.stamp>0&&current!=null){JSONObject pending=new JSONObject().put("chapter",current.id).put("paragraph",b.pos).put("fraction",b.fraction);entry.put("history",new JSONObject().put("chapter_url",current.url).put("last_read_at",b.stamp).put("visits",b.visits).put("locator",locator(c,store,pending)));}entries.put(entry);}if(entries.length()>0){JSONArray accepted=request(c,"POST","/v3/pocket/index",new JSONObject().put("entries",entries),true).getJSONArray("accepted");android.content.SharedPreferences.Editor edit=p.edit();for(int n=0;n<accepted.length();n++)edit.putBoolean("index_seeded:"+accepted.getString(n),true);edit.apply();}return more;}
    static void sync(Context c){if(!enabled(c))return;try{
        Store store=Store.get(c);android.content.SharedPreferences p=prefs(c);RelayClient cloud=new RelayClient(c);fastPositions(c,cloud);boolean cloudPending=false;if(cloud.ready())try{cloudSync(c,cloud);return;}catch(Exception cloudFailure){cloudPending=true;}if(seedIndex(c))worker.schedule(()->sync(c),2500,TimeUnit.MILLISECONDS);Map<String,?> snapshot=p.getAll();
        for(String key:snapshot.keySet())if(key.startsWith("pending:")){
            String saved=String.valueOf(snapshot.get(key));JSONObject pending=new JSONObject(saved);String bid=pending.getString("book");Store.Book b=store.book(bid);if(b==null)continue;Store.Chapter selected=store.chapter(bid,pending.getString("chapter"));if(selected==null)continue;
            JSONArray links=new JSONArray();List<Store.Chapter> chapters=store.chapters(bid);for(Store.Chapter ch:chapters)links.put(new JSONObject().put("title",ch.title).put("url",ch.url));JSONArray read=new JSONArray();for(String id:store.readingIds(bid,chapters))read.put(id);
            JSONObject payload=new JSONObject().put("position_policy","latest").put("update_position",!pending.getString("event_id").equals(p.getString("home_fast:"+bid,""))).put("book",new JSONObject().put("title",b.title).put("url",b.url)).put("chapters",links).put("chapter_url",selected.url).put("locator",locator(c,store,pending)).put("read",read);for(String field:new String[]{"sequence","event_id","base_revision","session"})payload.put(field,pending.get(field));payload.put("sequence",pending.getLong("sequence")*2+1);
            JSONObject result=request(c,"POST","/v2/bridge/push",payload,true);if(result.optBoolean("accepted")&&!result.optBoolean("conflict"))acknowledge(c,pending);
            synchronized(gate){android.content.SharedPreferences.Editor editor=p.edit();if(saved.equals(p.getString(key,""))){editor.remove(key);if(cloudPending)editor.putString("cloud_pending:"+bid,saved);}if(result.optBoolean("conflict")){editor.putString("conflict:"+bid,pending.toString());JSONObject remote=result.optJSONObject("current");if(remote!=null)editor.putString("remote:"+bid,remote.toString());}else if(result.has("revision"))editor.remove("conflict:"+bid).putLong("revision:"+bid,result.optLong("revision"));editor.commit();}
        }
        flushFlags(c);
        if(bundle(c)){status(c,"Đã đồng bộ hai chiều");ContentUpload.kick(c);return;}
        JSONObject library=request(c,"GET","/v1/library",null,true);JSONArray books=library.optJSONArray("books"),positions=library.optJSONArray("positions");HashMap<String,JSONObject> remotePositions=new HashMap<>();for(int n=0;positions!=null&&n<positions.length();n++){JSONObject position=positions.getJSONObject(n);remotePositions.put(position.optString("book"),position);}
        for(int n=0;books!=null&&n<books.length();n++){JSONObject book=books.getJSONObject(n);String bid=book.getString("id");JSONObject shared=library.optJSONObject("shared"),flags=shared==null?null:shared.optJSONObject(bid);if(flags!=null&&!p.getBoolean("flags:"+bid,false)){applying.set(true);try{if(flags.has("favorite"))store.pin(bid,flags.optBoolean("favorite"));if(flags.has("completed"))store.setCompleted(bid,flags.optBoolean("completed"));}finally{applying.remove();}}JSONObject remote=remotePositions.get(bid);Store.Book local=store.book(bid);long revision=remote==null?0:remote.optLong("revision");if(local!=null&&revision<=p.getLong("pulled:"+bid,0)&&book.optString("read_revision").equals(p.getString("readstate:"+bid,"")))continue;JSONObject data=remoteBook(c,bid);apply(c,data);if(!activeBook.equals(bid)&&!p.contains("pending:"+bid)&&!p.contains("conflict:"+bid))p.edit().putLong("pulled:"+bid,revision).putString("readstate:"+bid,book.optString("read_revision")).apply();}
        status(c,"Đã đồng bộ hai chiều");ContentUpload.kick(c);
    }catch(Exception e){status(c,"Chờ kết nối · Tiến độ vẫn lưu trên máy");}}
    static boolean bundle(Context c)throws Exception{
        Store store=Store.get(c);android.content.SharedPreferences p=prefs(c);JSONObject known=new JSONObject(),cache=new JSONObject();JSONArray wanted=new JSONArray();for(Store.Book book:store.books()){String signature=p.getString("bundle:"+book.id,"");if(!signature.isEmpty())known.put(book.id,signature);if(book.stamp>0||!book.current.isEmpty()||book.pinned||book.followed||store.isCompleted(book.id))wanted.put(book.id);int stored=0,total=0;for(Store.Chapter ch:store.chapters(book.id))if(!store.ignoredForReading(ch)&&!store.isHidden(book.id,ch.id)){total++;if(ch.ready)stored++;}cache.put(book.id,new JSONObject().put("stored",stored).put("total",total).put("complete",total>0&&stored==total));}
        JSONObject data=ServerSource.request(c,"POST","/v3/pocket/sync",new JSONObject().put("known",known).put("wanted",wanted).put("cache",cache));JSONArray documents=data.getJSONArray("documents");for(int n=0;n<documents.length();n++){JSONObject document=documents.getJSONObject(n);String bid=document.getJSONObject("book").getString("id");apply(c,document);if(!activeBook.equals(bid)&&!p.contains("pending:"+bid)&&!p.contains("conflict:"+bid))p.edit().putString("bundle:"+bid,document.getString("signature")).apply();}
        JSONObject shared=data.optJSONObject("shared");if(shared!=null)for(Iterator<String> ids=shared.keys();ids.hasNext();){String bid=ids.next();if(p.getBoolean("flags:"+bid,false)||store.book(bid)==null)continue;JSONObject flags=shared.getJSONObject(bid);applying.set(true);try{if(flags.has("favorite"))store.pin(bid,flags.optBoolean("favorite"));if(flags.has("completed"))store.setCompleted(bid,flags.optBoolean("completed"));}finally{applying.remove();}}
        rememberLatest(c,data.optString("latest_book"));
        if(data.optBoolean("more"))worker.schedule(()->sync(c),2500,TimeUnit.MILLISECONDS);return true;
    }
    static void apply(Context c,JSONObject data)throws Exception{apply(c,data,false);}
    static void apply(Context c,JSONObject data,boolean force)throws Exception{Store store=Store.get(c);android.content.SharedPreferences p=prefs(c);JSONObject book=data.getJSONObject("book");String bid=book.getString("id");applying.set(true);try{if(store.book(bid)==null)c.getSharedPreferences("settings",0).edit().putBoolean("remote_metadata_only_"+bid,true).apply();store.putBook(new HakoParser.Link(bid,book.getString("title"),HakoParser.sharedUrl(book.getString("url"))));android.content.SharedPreferences kinds=c.getSharedPreferences("settings",0);android.content.SharedPreferences.Editor kindsEdit=kinds.edit();boolean kindsChanged=false;Set<String> remoteHidden=new HashSet<>();JSONArray chapters=data.getJSONArray("chapters");ArrayList<HakoParser.Link> links=new ArrayList<>();for(int i=0;i<chapters.length();i++){JSONObject ch=chapters.getJSONObject(i);if(ch.optBoolean("hidden"))remoteHidden.add(ch.getString("id"));links.add(new HakoParser.Link(ch.getString("id"),ch.optString("title"),HakoParser.sharedUrl(ch.getString("url"))));String kind=ch.optString("kind");if(kind.equals("text")||kind.equals("illustration")){int value=kind.equals("illustration")?2:1;if(kinds.getInt("chapter_kind_"+ch.getString("id"),0)!=value){kindsEdit.putInt("chapter_kind_"+ch.getString("id"),value);kindsChanged=true;}}}if(kindsChanged){kindsEdit.apply();LibraryState.changed(c,bid,true);}if(!links.isEmpty()){StringBuilder key=new StringBuilder(HakoParser.ORIGIN);for(HakoParser.Link link:links)key.append('\n').append(link.id).append('|').append(link.title).append('|').append(link.url).append('|').append(remoteHidden.contains(link.id));byte[] hash=java.security.MessageDigest.getInstance("SHA-256").digest(key.toString().getBytes(StandardCharsets.UTF_8));String signature=android.util.Base64.encodeToString(hash,android.util.Base64.NO_WRAP);if(!signature.equals(p.getString("catalog_signature:"+bid,""))){store.catalog(bid,links);p.edit().putString("catalog_signature:"+bid,signature).apply();c.getSharedPreferences("settings",0).edit().putBoolean("catalog_failed_"+bid,true).apply();}}Set<String> hidden=new HashSet<>(c.getSharedPreferences("settings",0).getStringSet("hidden_chapters_"+bid,Collections.emptySet()));if(hidden.addAll(remoteHidden)){c.getSharedPreferences("settings",0).edit().putStringSet("hidden_chapters_"+bid,hidden).apply();LibraryState.changed(c,bid,true);}JSONObject availability=data.optJSONObject("availability");if(availability!=null){android.content.SharedPreferences display=c.getSharedPreferences("settings",0);String value=availability.toString();if(!value.equals(display.getString("shared_availability_"+bid,""))){display.edit().putString("shared_availability_"+bid,value).apply();LibraryState.changed(c,bid,true);}}if(book.has("followed"))store.followed(bid,book.optBoolean("followed"),book.optInt("shelf_rank",store.book(bid).shelfRank));JSONArray read=data.optJSONArray("read");for(int i=0;read!=null&&i<read.length();i++)store.readChapter(read.getString(i));JSONObject position=data.optJSONObject("position");if(position==null){JSONObject history=data.optJSONObject("history");if(history!=null)store.sharedReadingStats(bid,history.optInt("visits"),history.optLong("last_read_at"));return;}
            if(position.optLong("revision")<p.getLong("revision:"+bid,0))return;
            p.edit().putString("remote:"+bid,position.toString()).apply();if(activeBook.equals(bid)||!force&&(p.contains("pending:"+bid)||p.contains("conflict:"+bid)))return;
            String cid=position.optString("legacy_chapter",position.optString("chapter").replaceFirst("-c([0-9]+)$","-$1"));JSONObject loc=position.optJSONObject("portable");int paragraph=loc==null?0:loc.optInt("paragraph");float fraction=loc==null?0:(float)loc.optDouble("fraction");if(loc!=null){ContentAnchor.Position mapped=mapped(c,store,cid,loc);paragraph=mapped.paragraph;fraction=mapped.fraction;p.edit().putString("resume_locator:"+bid,new JSONObject().put("chapter",cid).put("locator",loc).toString()).commit();}else p.edit().remove("resume_locator:"+bid).commit();
            store.position(bid,cid,paragraph,fraction);store.sharedReadingStats(bid,loc==null?0:loc.optInt("visits"),loc==null?position.optLong("updated_at"):loc.optLong("last_read_at",position.optLong("updated_at")));android.content.SharedPreferences.Editor applied=p.edit().putLong("revision:"+bid,position.optLong("revision"));if(!position.optString("device").equals(p.getString("device","")))applied.remove("cloud_pending:"+bid);applied.apply();
        }finally{applying.remove();}}
    static JSONObject remoteBook(Context c,String bid)throws Exception{RelayClient cloud=new RelayClient(c);if(cloud.ready())try{JSONObject snapshot=cloud.snapshot(activeBook);JSONArray books=snapshot.getJSONArray("books");for(int i=0;i<books.length();i++)if(bid.equals(books.optJSONObject(i).optString("id")))return RelayClient.document(cloud.entry(books.getJSONObject(i)),snapshot.optJSONArray("positions"),snapshot.optJSONObject("read"),true);}catch(Exception unavailable){}return request(c,"GET","/v2/bridge/books/"+bid,null,true);}
    static void cloudSync(Context c,RelayClient cloud)throws Exception{Store store=Store.get(c);android.content.SharedPreferences p=prefs(c);android.content.SharedPreferences settings=c.getSharedPreferences("settings",0);for(Store.Book existing:store.books()){if(!p.getBoolean("cloud_seeded:"+existing.id,false)){if(existing.pinned||store.isCompleted(existing.id))p.edit().putBoolean("flags:"+existing.id,true).putBoolean("seed_flags:"+existing.id,true).commit();p.edit().putBoolean("cloud_seeded:"+existing.id,true).commit();}JSONArray marks;try{marks=new JSONArray(settings.getString("marks-"+existing.id,"[]"));}catch(Exception e){continue;}boolean changed=false;for(int n=0;n<marks.length();n++){JSONObject mark=marks.getJSONObject(n);if(mark.optString("id").isEmpty()){mark.put("id",UUID.randomUUID().toString());changed=true;}if(!p.getBoolean("mark_synced:"+mark.getString("id"),false))bookmark(c,existing.id,mark,false,false);}if(changed)settings.edit().putString("marks-"+existing.id,marks.toString()).commit();}for(String key:p.getAll().keySet())if(key.startsWith("pending:")||key.startsWith("cloud_pending:")){String saved=p.getString(key,"{}");JSONObject pending=new JSONObject(saved);String bid=pending.getString("book");Store.Book b=store.book(bid);Store.Chapter current=store.chapter(bid,pending.getString("chapter"));if(b==null||current==null)continue;JSONArray chapters=new JSONArray(),read=new JSONArray();List<Store.Chapter> all=store.chapters(bid);Set<String> known=store.readingIds(bid,all);for(Store.Chapter ch:all){chapters.put(new JSONObject().put("title",ch.title).put("url",ch.url));if(known.contains(ch.id))read.put(RelayClient.chapterId(ch.url));}JSONObject event=new JSONObject().put("update_position",!pending.getString("event_id").equals(p.getString("cloud_fast:"+bid,""))).put("book",bid).put("chapter",RelayClient.chapterId(current.url)).put("locator",locator(c,store,pending)).put("read_ids",read).put("metadata",new JSONObject().put("book",new JSONObject().put("id",bid).put("title",b.title).put("url",b.url)).put("chapters",chapters)).put("relay_base_revision",pending.optLong("relay_base_revision",0));for(String field:new String[]{"sequence","event_id","session"})event.put(field,pending.get(field));event.put("sequence",pending.getLong("sequence")*2+1);JSONObject result=cloud.send(event);synchronized(gate){android.content.SharedPreferences.Editor edit=p.edit();if(saved.equals(p.getString(key,"")))edit.remove(key);if(result.optBoolean("conflict"))edit.putString("conflict:"+bid,pending.toString());else if(result.has("revision"))edit.remove("conflict:"+bid).putLong("revision:"+bid,result.optLong("revision"));edit.commit();}}
        for(String key:p.getAll().keySet())if(key.startsWith("flags:")&&p.getBoolean(key,false)){String bid=key.substring(6);Store.Book b=store.book(bid);if(b!=null){JSONObject values=new JSONObject().put("favorite",b.pinned).put("completed",store.isCompleted(bid));if(p.getBoolean("seed_flags:"+bid,false)){JSONObject remote=cloud.snapshot().optJSONObject("shared");remote=remote==null?null:remote.optJSONObject(bid);if(remote!=null)values.put("favorite",b.pinned||remote.optBoolean("favorite")).put("completed",store.isCompleted(bid)||remote.optBoolean("completed"));}cloud.flags(bid,values);p.edit().remove(key).remove("seed_flags:"+bid).apply();}}
        for(String key:p.getAll().keySet())if(key.startsWith("mark:")){String saved=p.getString(key,"{}");JSONObject item=new JSONObject(saved);cloud.bookmark(item.getString("book"),item.getJSONObject("value"));if(saved.equals(p.getString(key,"")))p.edit().remove(key).putBoolean("mark_synced:"+item.getJSONObject("value").getString("id"),true).apply();}
        JSONObject snapshot=cloud.snapshot(activeBook);JSONArray books=snapshot.optJSONArray("books");for(int i=0;books!=null&&i<books.length();i++){JSONObject entry=books.getJSONObject(i);String bid=entry.getString("id");JSONObject data=RelayClient.document(cloud.entry(entry),snapshot.optJSONArray("positions"),snapshot.optJSONObject("read"),true);JSONObject position=data.optJSONObject("position");String fingerprint=entry.optLong("metadata_revision")+":"+data.optJSONArray("read")+":"+(position==null?0:position.optLong("revision"));if(!fingerprint.equals(p.getString("cloud_pulled:"+bid,""))){apply(c,data);if(!activeBook.equals(bid)&&!p.contains("pending:"+bid)&&!p.contains("conflict:"+bid))p.edit().putString("cloud_pulled:"+bid,fingerprint).apply();}if(position!=null&&!p.contains("pending:"+bid)&&!p.contains("conflict:"+bid))cloud.observed(bid,position.optLong("revision"));JSONObject flags=snapshot.optJSONObject("shared");flags=flags==null?null:flags.optJSONObject(bid);if(flags!=null&&!p.getBoolean("flags:"+bid,false)){applying.set(true);try{store.pin(bid,flags.optBoolean("favorite"));store.setCompleted(bid,flags.optBoolean("completed"));}finally{applying.remove();}}
            JSONArray marks=snapshot.optJSONArray("bookmarks"),selected=new JSONArray();for(int n=0;marks!=null&&n<marks.length();n++){JSONObject m=marks.getJSONObject(n);if(!bid.equals(m.optString("book")))continue;String cid=m.optString("chapter").replaceFirst("-c([0-9]+)$","-$1");JSONObject loc=m.optJSONObject("portable");JSONObject anchor=m.optJSONObject("anchor");int paragraph=loc!=null?loc.optInt("paragraph"):anchor==null?0:anchor.optInt("block");float fraction=loc==null?0:(float)loc.optDouble("fraction");selected.put(new JSONObject().put("id",m.optString("id")).put("chapter",cid).put("pos",paragraph).put("fraction",fraction).put("title",m.optString("label","Đánh dấu")));}c.getSharedPreferences("settings",0).edit().putString("marks-"+bid,selected.toString()).apply();}
        status(c,"Đã đồng bộ qua Cloudflare · Không phụ thuộc server nhà");
    }
    public static void bookmark(Context c,String bid,JSONObject mark,boolean deleted){bookmark(c,bid,mark,deleted,true);}
    static void bookmark(Context c,String bid,JSONObject mark,boolean deleted,boolean schedule){if(!enabled(c))return;try{String id=mark.optString("id");if(id.isEmpty())return;Store store=Store.get(c);Store.Chapter ch=store.chapter(bid,mark.optString("chapter"));if(ch==null)return;JSONObject pending=new JSONObject().put("chapter",ch.id).put("paragraph",mark.optInt("pos")).put("fraction",mark.optDouble("fraction"));JSONObject value=new JSONObject().put("id",id).put("chapter",RelayClient.chapterId(ch.url)).put("label",mark.optString("title")).put("portable",locator(c,store,pending)).put("deleted",deleted);prefs(c).edit().putString("mark:"+id,new JSONObject().put("book",bid).put("value",value).toString()).commit();if(schedule)kick(c);}catch(Exception ignored){}}
    static void choosePosition(Activity activity){Context c=activity.getApplicationContext();ArrayList<String> books=new ArrayList<>(),labels=new ArrayList<>();Store store=Store.get(c);for(String key:prefs(c).getAll().keySet())if(key.startsWith("remote:")){String bid=key.substring(7);books.add(bid);Store.Book b=store.book(bid);labels.add((prefs(c).contains("conflict:"+bid)?"Cần chọn vị trí · ":"")+(b==null?bid:b.title));}new ReaderDialogBuilder(activity).setTitle("Vị trí dùng chung").setItems(labels.toArray(new String[0]),(d,n)->{String bid=books.get(n);new ReaderDialogBuilder(activity).setTitle("Tiếp tục từ đâu?").setMessage("Giữ tiến độ của app này hoặc nhận vị trí mới nhất từ hệ thống đồng bộ.").setPositiveButton("Dùng vị trí chung",(x,w)->worker.execute(()->{try{JSONObject data=remoteBook(c,bid);JSONObject position=data.optJSONObject("position");if(position==null)return;Runnable change=()->{try{prefs(c).edit().remove("pending:"+bid).remove("conflict:"+bid).apply();new RelayClient(c).resolve(bid,position.optLong("revision"));apply(c,data,true);}catch(Exception e){status(c,"Chưa nhận được vị trí");}};activity.runOnUiThread(()->{if(activity instanceof MainActivity)((MainActivity)activity).bridgeResume(bid,position.optString("legacy_chapter"),change);});}catch(Exception e){activity.runOnUiThread(()->Toast.makeText(activity,"Chưa kết nối được. Tiến độ trên máy được giữ.",Toast.LENGTH_LONG).show());}})).setNeutralButton("Giữ vị trí app này",(x,w)->worker.execute(()->{try{JSONObject data=remoteBook(c,bid);JSONObject remote=data.optJSONObject("position");new RelayClient(c).resolve(bid,remote==null?0:remote.optLong("revision"));prefs(c).edit().remove("conflict:"+bid).putLong("revision:"+bid,remote==null?0:remote.optLong("revision")).putString("session:"+bid,UUID.randomUUID().toString()).commit();Store.Book b=store.book(bid);if(b!=null)localPosition(c,bid,b.current,b.pos,b.fraction);sync(c);}catch(Exception e){status(c,"Đã giữ vị trí trên máy · Chờ kết nối");}})).setNegativeButton("Để sau",null).show();}).setNegativeButton("Đóng",null).show();}
    public static void settings(Activity activity){Context c=activity.getApplicationContext();if(enabled(c)){new ReaderDialogBuilder(activity).setTitle("Thiết bị đã liên kết").setMessage(prefs(c).getString("status","Đồng bộ tự động khi rời chương")+"\nTiến độ tự gửi, không cần bấm đồng bộ.\n"+ContentUpload.prefs(c).getString("status","Nội dung local tự gửi sau vị trí")).setPositiveButton("Đóng",null).setNeutralButton("Ngắt liên kết",(d,w)->new ReaderDialogBuilder(activity).setTitle("Ngắt liên kết thiết bị?").setMessage("Giữ dữ liệu và hàng chờ trên máy. Bạn cần liên kết lại để tiếp tục đồng bộ.").setPositiveButton("Ngắt",(a,b)->prefs(c).edit().remove("token").remove("device").apply()).setNegativeButton("Giữ lại",null).show()).show();return;}LinearLayout box=new LinearLayout(activity);box.setOrientation(1);TextView state=new TextView(activity);state.setPadding(20,16,20,16);state.setText(prefs(c).getString("status","Liên kết để dùng chung tiến độ với Hako Server. Mỗi app vẫn đọc độc lập khi mất kết nối."));box.addView(state);TextView automatic=new TextView(activity);automatic.setText("Tự gửi vị trí khi rời chương. Không cần chọn vị trí giữa hai máy.");automatic.setPadding(20,8,20,12);box.addView(automatic);EditText code=new EditText(activity);code.setHint("Mã 6 số từ /hako");code.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);box.addView(code);AlertDialog dialog=new ReaderDialogBuilder(activity).setTitle("Đồng bộ Hako Server").setView(box).setPositiveButton("Liên kết",null).setNegativeButton("Đóng",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String value=code.getText().toString().trim();if(!value.matches("[0-9]{6}")){state.setText("Nhập đủ 6 chữ số");return;}state.setText("Đang chờ duyệt trên /hako…");worker.execute(()->{try{JSONObject ticket=request(c,"POST","/pair/request",new JSONObject().put("code",value).put("name","Hako Pocket · "+Build.MODEL),false);for(int i=0;i<150;i++){Thread.sleep(1800);JSONObject result=request(c,"POST","/pair/poll",ticket,false);if(result.optString("state").equals("rejected"))throw new IOException("Yêu cầu bị từ chối");if(result.optString("state").equals("approved")){prefs(c).edit().putString("token",result.getString("token")).putString("device",result.getString("device")).commit();activity.runOnUiThread(()->state.setText("Đã liên kết. Đang đồng bộ thư viện và vị trí đọc."));sync(c);return;}}throw new IOException("Mã đã hết hạn");}catch(Exception e){activity.runOnUiThread(()->state.setText("Chưa liên kết. Tạo mã mới trên /hako rồi thử lại."));}});}));dialog.show();}
}
